using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct WorldId : IEquatable<WorldId>, IComparable<WorldId>
    {
        public Guid Value { get; }

        public WorldId(Guid value)
        {
            Value = value;
        }

        public static WorldId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static WorldId NewRandom() => new WorldId(Guid.NewGuid());

        public static WorldId Parse(string text) => new WorldId(Guid.Parse(text));

        public static bool TryParse(string text, out WorldId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new WorldId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(WorldId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is WorldId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(WorldId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(WorldId left, WorldId right) => left.Equals(right);

        public static bool operator !=(WorldId left, WorldId right) => !left.Equals(right);
    }
}
